e v-if="returning && batchReturning && selectedReturnSource"><el-form-item label="原出库净重(g)"><el-input :model-value="String(selectedReturnSource.netWeight)" readonly/></el-form-item><el-form-item label="剩余可退净重(g)" class="return-limit-field" :class="{'return-limit-empty':!refreshingReturn&&!returnLoadError&&sourceAvailable(selectedReturnSource)==='0.000000'}">
 <div class="return-limit-content">
