<script setup lang="ts">
import type {FormInstance,FormRules} from 'element-plus'
import {fieldRule,textRules,integerError,decimalError,applyFieldErrors} from '@/utils/input-validation'
import { useActionPermission } from '@/composables/useActionPermission'
const actionPermission = useActionPermission()
import {rawReturnAvailable,rawReturnError,rawReturnSourceUsable} from '@/utils/raw-return-allowance'
import {receivingOrganizationText} from '@/utils/receiving-organization'
import {personLabel} from '@/utils/person-label'
import {stockOptionMain,stockOptionDetail,stockOptionLabel} from '@/utils/stock-option-label'
import {stockAvailabilityError,releasedTransferError,externalEntryError} from '@/utils/stock-availability'
import {createUUID} from '@/utils/uuid'
import{ref,reactive,computed,nextTick,watch,onBeforeUnmount}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import useUserStore from '@/store/modules/user';import request from '@/utils/request';import{productionStockOptions,warehouseOptions,warehouseWorkOrderContext,warehouseSave,warehouseDetail,importWarehouseLines,orderTypeNames,type Row,type EntryContext,type ProductionStockResponse}from'@/api/metal/warehouse';
const headerForm=ref<FormInstance>(),lineForm=ref<FormInstance>(),lineQuantityInput=ref<string>(),completedQuantityInput=ref<string>()
const headerModel=computed(()=>({...form,itemId:itemId.value,processId:processId.value}))
const selection=(label:string)=>[fieldRule(v=>v?'':'请选择'+label,'change')]
const headerRules:FormRules={factoryId:selection('工厂'),type:selection('单据类型'),sourceOrderId:selection('对应出库工单'),workOrderId:[fieldRule(v=>form.type==='PRODUCTION_OUT'&&!v?'请选择生产工单':'','change')],itemId:selection('产品明细'),processId:selection('工序'),warehouseId:selection('仓库/库房'),orderDate:selection('单据日期'),reason:textRules('还库原因',500,true),completedQuantity:[fieldRule(v=>integerError(completedQuantityInput.value??v,'实际完成数量'),['blur','change'])]}
const lineRules:FormRules={choiceId:selection('物料'),quantity:[fieldRule(v=>integerError(lineQuantityInput.value??v,'数量'),['blur','change'])],netWeight:[fieldRule(v=>decimalError(v,'实测净重',{positive:form.type!=='RAW_RETURN'}))],grossWeight:[fieldRule(v=>decimalError(v,'毛重',{optional:true}))],impurity:[fieldRule(v=>decimalError(v,'杂质',{optional:true}))],purity:[fieldRule(v=>decimalError(v,'纯度',{optional:true,integer:6,max:100}))],organization:textRules('单位名称',100),receivingOrganization:textRules('收货单位',100),purpose:textRules('用途',200),remark:textRules('备注',500),batchNo:textRules('批次号',160)}
const emit=defineEmits(['saved','busy-change','complete-batch']),visible=ref(false),busy=ref(false),loading=ref(false),kind=ref('OUT'),opening=ref(false),form=reactive<Row>({}),factories=ref<Row[]>([]),warehouses=ref<Row[]>([]),people=ref<Row[]>([]),orders=ref<Row[]>([]),batches=ref<Row[]>([]),stocks=ref<Row[]>([]),materials=ref<Row[]>([]),products=ref<Row[]>([]),sources=ref<Row[]>([]),items=ref<Row[]>([]),itemId=ref(''),processId=ref(''),selected=ref<Row[]>([]),lineVisible=ref(false),checkingStock=ref(false),line=reactive<Row>({}),lineIndex=ref(-1),fileRef=ref<HTMLInputElement>();
let optionEpoch=0,detailEpoch=0,openEpoch=0,returnEpoch=0,disposed=false;
const settlementQuantity=ref<HTMLElement>();
async function revealCompletedQuantity(){const session=openEpoch;if(!form.settle)return;await nextTick();if(!disposed&&visible.value&&session===openEpoch&&form.settle)settlementQuantity.value?.scrollIntoView({block:'nearest',inline:'nearest'})}

const recoveryContext=ref<Row>(),recoveryLoading=ref(false),recoveryError=ref('');let recoveryEpoch=0;
const recovery=computed(()=>form.type==='PROCESS_RAW_RETURN');
const productionStocks=ref<Row[]>([]),productionStockLoading=ref(false),sharedEntryContext=ref<EntryContext>();let stockEpoch=0;
const entryKeys=['factoryId','warehouseId','workOrderId','itemId','processId'] as const;
function entryParams(){return {factoryId:form.factoryId,warehouseId:form.warehouseId,workOrderId:form.workOrderId,itemId:itemId.value,processId:processId.value}}
function validEntryContext(value:EntryContext|undefined,params:Row){return !!value&&typeof value.externalEntryCapacity==='string'&&/^\d+$/.test(value.externalEntryCapacity)&&entryKeys.every(key=>String(value[key])===String(params[key]))}
function publishSharedContext(response:ProductionStockResponse,params:Row){sharedEntryContext.value=validEntryContext(response.entryContext,params)?{...response.entryContext!}:undefined}
const activeSharedContext=computed(()=>validEntryContext(sharedEntryContext.value,entryParams())?sharedEntryContext.value:undefined);
const sharedFilled=computed(()=>form.lines?.filter((row:Row)=>row.releaseId).reduce((n:bigint,row:Row)=>n+BigInt(row.quantity??0),0n)??0n);
const sharedRemaining=computed(()=>activeSharedContext.value?BigInt(activeSharedContext.value.externalEntryCapacity)-sharedFilled.value:undefined);
const sharedLineRemaining=computed(()=>activeSharedContext.value?BigInt(activeSharedContext.value.externalEntryCapacity)-(form.lines??[]).filter((row:Row,index:number)=>index!==lineIndex.value&&row.releaseId).reduce((n:bigint,row:Row)=>n+BigInt(row.quantity??0),0n):undefined);
const refreshingReturn=ref(false),returnLoadError=ref(false);
