function choiceChanged(value:string){lineQuantityInput.value=undefined;lineForm.value?.clearValidate();const o=choices.value.find(o=>(o.choiceKey||o.id)===value);if(!o)return;if(out.value)line.organization=o.organization??'';line.code=o.code||'';line.name=o.name;line.specification=o.specification||'';line.unit='件';if(recovery.value){line.category='RAW';line.referenceId=o.id;line.organization=form.workOrderCustomer??'';line.batchNo='';line.sourceLineId=null;line.inventoryId=null}else if(out.value){line.inventoryId=o.id;line.releaseId=o.releaseId??null;line.skipPermitId=o.skipPermitId??null;line.skipPermitVersion=o.skipPermitVersion??null;line.skipAcknowledged=false;line.skippedSequences=o.skippedSequences??[];line.category=o.category;line.referenceId=o.referenceId}else if(returning.value){line.organization=o.organization??'';line.sourceLineId=o.id;line.category=o.category;line.referenceId=o.referenceId;line.batchNo=o.batchNo}else{line.referenceId=o.id}if(line.category==='RAW')line.quantity=0;else if(!line.quantity)line.quantity=1}
function deriveNet(){const valid=(value:string)=>/^\d{1,14}(\.\d{0,6})?$/.test(value);if(line.grossWeight&&valid(line.grossWeight)&&(!line.impurity||valid(line.impurity))){const units=(value:string)=>{const [integer,fraction='']=value.split('.');return BigInt(integer||'0')*1000000n+BigInt(fraction.padEnd(6,'0'))};const result=units(line.grossWeight)-units(line.impurity||'0'),positive=result<0n?-result:result;line.netWeight=(result<0n?'-':'')+(positive/1000000n)+'.'+(positive%1000000n).toString().padStart(6,'0')}}
function weightError(key:string){const value=String(line[key]??'');if(!value)return key==='netWeight'?'请输入实测净重':'';if(!/^[0-9]{1,14}(\.[0-9]{1,6})?$/.test(value))return '请输入非负数字，整数最多14位、小数最多6位';if(key==='netWeight'&&form.type!=='RAW_RETURN'&&Number(value)<=0)return '实测净重必须大于0';return ''}
function purityError(){if(line.category==='RAW')return '';const value=String(line.purity??'');if(!value)return '';if(!/^\d{1,6}(\.\d{1,6})?$/.test(value))return '请输入数字，最多6位小数';if(Number(value)>100)return '纯度请输入0～100之间的数字';return ''}
function weightUnits(value:string){const [integer,fraction='']=value.split('.');return BigInt(integer)*1000000n+BigInt(fraction.padEnd(6,'0'))}
async function validateOutgoingLines(incoming:Row[],editingIndex=-1,replaceAll=false){
 const session=openEpoch,factory=form.factoryId,warehouse=form.warehouseId,type=form.type;
 const target=[form.workOrderId,itemId.value,processId.value,detailEpoch,stockEpoch];const isCurrent=()=>!disposed&&session===openEpoch&&factory===form.factoryId&&warehouse===form.warehouseId&&type===form.type&&target.every((v,i)=>v===[form.workOrderId,itemId.value,processId.value,detailEpoch,stockEpoch][i]);
 const params=entryParams();if(type==='PRODUCTION_OUT')sharedEntryContext.value=undefined;
 const response=type==='PRODUCTION_OUT'?await productionStockOptions(params,isCurrent):await warehouseOptions('stocks',factory);if(!isCurrent())return false;stocks.value=response.data;if(type==='PRODUCTION_OUT')publishSharedContext(response as ProductionStockResponse,params)
 const pending=replaceAll?[]:form.lines.filter((_:Row,index:number)=>index!==editingIndex)
 for(const [index,row]of incoming.entries()){
  const stock=stocks.value.find(o=>o.id===row.inventoryId&&String(o.releaseId??'')===String(row.releaseId??'')&&o.warehouseId===form.warehouseId&&o.category===row.category)
  if(stock&&(String(stock.skipPermitId??'')!==String(row.skipPermitId??'')||String(stock.skipPermitVersion??'')!==String(row.skipPermitVersion??''))){ElMessage.error('工艺跳步许可或版本已变化，请重新选择');return false}
  if(row.skipPermitId&&!row.skipAcknowledged){ElMessage.error('请确认工艺跳步许可及跳过工序');return false}
  if(!stock){ElMessage.error('所选库存已失效或不属于当前库房，请重新选择');return false}
  const error=stockAvailabilityError(stock as {netWeight:string;quantity:number;category:string},row,pending)
  if(error){ElMessage.error((incoming.length>1?'导入第'+(index+1)+'条：':'')+error);return false}
  if(row.releaseId){const releaseError=stockAvailabilityError({netWeight:stock.availableWeight,quantity:stock.availableQuantity,category:'SEMI'},row,pending.filter((p:Row)=>p.releaseId===row.releaseId));if(releaseError){ElMessage.error('释放额度不足：'+releaseError);return false}}
  pending.push(row)
 }
 for(const releaseId of new Set(pending.filter((row:Row)=>row.releaseId).map((row:Row)=>String(row.releaseId)))){
  const pool=stocks.value.find(o=>String(o.releaseId??'')===releaseId)
  if(!pool){ElMessage.error('释放记录'+releaseId+'已失效，请重新选择');return false}
  const error=releasedTransferError({quantity:pool.releaseRemainingQuantity??pool.availableQuantity,netWeight:pool.releaseRemainingWeight??pool.availableWeight},pending.filter((row:Row)=>String(row.releaseId??'')===releaseId))
  if(error){ElMessage.error('释放记录'+releaseId+'：'+error);return false}
 }
 if(type==='PRODUCTION_OUT'&&pending.some((row:Row)=>row.releaseId)){
  if(!activeSharedContext.value){ElMessage.error('共享接入额度未就绪，请刷新重试');return false}
  const error=externalEntryError(activeSharedContext.value.externalEntryCapacity,pending)
  if(error){ElMessage.error(error);return false}
 }
 return true
}
async function confirmLine(){const validationSession=openEpoch,validationReturn=returnEpoch,validationChoice=line.choiceId;if(!await lineForm.value?.validate().catch(()=>false)||validationSession!==openEpoch||validationReturn!==returnEpoch||validationChoice!==line.choiceId||!lineVisible.value)return;if(line.category!=='RAW')line.quantity=Number(line.quantity);
 if(recovery.value&&recoveryLoading.value)return;
 const lineContext=[openEpoch,detailEpoch,stockEpoch,form.factoryId,form.warehouseId,form.workOrderId,itemId.value,processId.value,form.type];const lineCurrent=()=>!disposed&&lineVisible.value&&lineContext.every((v,i)=>v===[openEpoch,detailEpoch,stockEpoch,form.factoryId,form.warehouseId,form.workOrderId,itemId.value,processId.value,form.type][i]);
 const productError=outputProductError([line]);if(productError){ElMessage.error(productError);return}
 if(purityError()){ElMessage.error(purityError());return}
 if(recovery.value&&!await validateRecovery([{...line}],lineIndex.value))return;
 if(kind.value==='IN'&&!opening.value&&form.workOrderId&&line.category!=='RAW')line.organization=form.workOrderCustomer??'';if(checkingStock.value||refreshingReturn.value||returnLoadError.value)return;for(const key of ['grossWeight','impurity','netWeight']){const error=weightError(key);if(error){ElMessage.error(error);return}}if(line.grossWeight){const gross=weightUnits(String(line.grossWeight)),impurity=weightUnits(String(line.impurity||'0'));if(impurity>gross){ElMessage.error('杂质不能超过毛重');return}if(gross-impurity!==weightUnits(String(line.netWeight))){ElMessage.error('实测净重必须等于毛重减杂质');return}}if(!line.choiceId||!/^\d+(\.\d{1,6})?$/.test(String(line.netWeight))||(Number(line.netWeight)<0||(form.type!=='RAW_RETURN'&&Number(line.netWeight)===0))||(line.category!=='RAW'&&(!Number.isInteger(line.quantity)||line.quantity<1))){ElMessage.error(form.type==='RAW_RETURN'?'请选择物料并填写非负净重及合法数量':'请选择物料并填写正数净重及合法数量');return}const session=openEpoch;if(batchReturning.value){checkingStock.value=true;try{if(!await validateRawReturns([{...line}],lineIndex.value,false,true))return}finally{if(!disposed&&session===openEpoch)checkingStock.value=false}}if(out.value){checkingStock.value=true;try{if(!await validateOutgoingLines([line],lineIndex.value))return}catch{ElMessage.error('库存校验失败，请重试，本条物料尚未加入清单');return}finally{if(!disposed&&session===openEpoch)checkingStock.value=false}}if(!lineCurrent())return;if(lineIndex.value<0)form.lines.push({...line});else form.lines[lineIndex.value]={...line};lineVisible.value=false}
function removeLines(){form.lines=form.lines.filter((r:Row)=>!selected.value.includes(r));selected.value=[]}
async function download(){const data=await request({url:'/metal/warehouse-order/template',params:(kind.value==='IN'&&!opening.value||recovery.value)?{type:form.type,batchBound:!!form.batchId}:undefined,responseType:'blob'});const url=URL.createObjectURL(data as unknown as Blob);const a=document.createElement('a');a.href=url;a.download='仓储物料模板.xlsx';a.click();URL.revokeObjectURL(url)}
async function importFile(event:Event){if(returning.value&&batchReturning.value&&!form.sourceOrderId){ElMessage.error('请先选择对应出库工单');(event.target as HTMLInputElement).value='';return}const input=event.target as HTMLInputElement;const file=input.files?.[0];if(!file||dependenciesLoading.value||busy.value)return;const session=openEpoch,epoch=++optionEpoch;const outputContext=[form.factoryId,form.workOrderId,itemId.value,processId.value,form.type];const current=()=>!disposed&&session===openEpoch&&epoch===optionEpoch&&outputContext.every((v,i)=>v===[form.factoryId,form.workOrderId,itemId.value,processId.value,form.type][i]);loading.value=true;try{const r=await importWarehouseLines(file,{...form,itemId:itemId.value,processId:processId.value});if(!current())return;if(recovery.value&&!await validateRecovery((r as any).data))return;if(form.lines.length+(r as any).data.length>1000){ElMessage.error('物料清单合计最多1000行，本次导入未追加');return}if(returning.value&&batchReturning.value&&(r as any).data.some((row:Row)=>!sources.value.some(o=>o.id===row.sourceLineId&&o.orderId===form.sourceOrderId))){ElMessage.error('导入物料必须来自所选出库工单');return}if(batchReturning.value&&!await validateRawReturns((r as any).data))return;if(out.value&&(r as any).data.some((row:Row)=>row.skipPermitId)){try{await ElMessageBox.confirm('导入包含工艺许可跳步领料；跳过工序不会生成报工。请确认本次工艺许可。','工艺跳步确认',{type:'warning',confirmButtonText:'确认跳步领料',cancelButtonText:'取消'})}catch{return}if(!current())return;for(const row of (r as any).data)if(row.skipPermitId)row.skipAcknowledged=true;}if(out.value&&!await validateOutgoingLines((r as any).data))return;if(!current())return;const productError=outputProductError((r as any).data,true);if(productError){ElMessage.error(productError);return}form.lines.push(...(r as any).data.map((row:Row)=>kind.value==='IN'&&!opening.value&&form.workOrderId&&row.category!=='RAW'?{...row,organization:form.workOrderCustomer??''}:row));ElMessage.success('已填充明细，确认后才会过账')}finally{if(!disposed&&session===openEpoch&&epoch===optionEpoch){loading.value=false;input.value=''}}}
function openReturnConfirmation(){const b=batches.value.find(b=>b.completionPolicy==='SINGLE_OUTPUT_RETURN'&&String(b.workOrderId)===String(form.workOrderId)&&String(b.itemId)===String(itemId.value)&&String(b.processId)===String(processId.value));if(!b)return;visible.value=false;emit('complete-batch',String(b.id))}
async function save(){if(busy.value||dependenciesLoading.value)return;if(singleBatch.value&&returning.value){openReturnConfirmation();return}const validationSession=openEpoch;if(!await headerForm.value?.validate().catch(()=>false)||validationSession!==openEpoch||!visible.value)return;if(singleBatch.value)form.settle=false;if(form.settle)form.completedQuantity=Number(form.completedQuantity);const productError=outputProductError(form.lines);if(productError){ElMessage.error(productError);return}if(returning.value&&batchReturning.value&&(!form.sourceOrderId||form.lines.some((row:Row)=>!sources.value.some(o=>o.id===row.sourceLineId&&o.orderId===form.sourceOrderId)))){ElMessage.error('请选择对应出库工单，物料必须来自该单据');return}if((form.type==='SEMI_RETURN'||recovery.value)&&!String(form.reason??'').trim()){ElMessage.error(recovery.value?'请填写加工余料还库原因':'请填写半成品还库原因');return}if(!form.factoryId||!form.warehouseId||!form.orderDate||(form.type!=='PRODUCTION_OUT'&&!form.operatorIds?.length)||!form.keeperId||!form.lines.length){ElMessage.error('请选择工厂、库房、日期、经办人、仓管员并添加物料');return}if((['PRODUCTION_OUT','RAW_RETURN','SEMI_RETURN','PROCESS_RAW_RETURN'].includes(form.type)||form.workOrderId)&&(!form.workOrderId||!itemId.value||!processId.value)){ElMessage.error('请选择生产工单、产品明细和工序');return}if(form.settle&&(!Number.isInteger(form.completedQuantity)||form.completedQuantity<1)){ElMessage.error('请填写正整数实际完成数量');return}const session=openEpoch;busy.value=true;try{if(recovery.value&&!await validateRecovery(form.lines,-1,true))return;if(form.type==='RAW_RETURN'&&!await validateRawReturns(form.lines,-1,true))return;if(out.value&&!await validateOutgoingLines(form.lines,-1,true))return;if(disposed||session!==openEpoch)return;const data={...form,batchId:recovery.value?form.batchId:null,batchVersion:recovery.value?form.batchVersion:null,itemId:form.workOrderId?itemId.value:null,processId:form.workOrderId?processId.value:null,workOrderId:form.workOrderId||null,recipientId:form.recipientId||null,inspectorId:form.inspectorId||null,reviewerId:form.reviewerId||null,lines:form.lines.map((r:Row)=>({...r,grossWeight:r.grossWeight||null,impurity:r.impurity||null,purity:r.purity||null}))};const result:any=await warehouseSave(opening.value?'inventory/opening':'warehouse-order',JSON.parse(JSON.stringify(data)));if(disposed||session!==openEpoch)return;let completionId='';if(boundOutput.value&&result.id){try{const posted=(await warehouseDetail('warehouse-order',String(result.id))).data;if(disposed||session!==openEpoch)return;if(posted.completionPolicy==='SINGLE_OUTPUT_RETURN')completionId=String(posted.batchId)}catch{ElMessage.warning('入库已生效，请从单据详情继续还料确认')}}if(disposed||session!==openEpoch)return;visible.value=false;ElMessage.success('单据已生效');emit('saved');if(completionId)emit('complete-batch',completionId)}catch(error){if(!disposed&&session===openEpoch)applyFieldErrors(headerForm.value,error)}finally{busy.value=false}}
async function openNextStep(context:Row){
 await open('OUT');if(disposed||!visible.value)return;const session=openEpoch;
 if(String(form.factoryId)!==String(context.factoryId))await changeFactory(String(context.factoryId));
 if(disposed||session!==openEpoch||!visible.value)return;
 form.workOrderId=String(context.workOrderId);await orderChanged();
 if(disposed||session!==openEpoch||!visible.value||!items.value.some(i=>String(i.id)===String(context.itemId)))return;
 itemId.value=String(context.itemId);if(!steps.value.some((s:Row)=>String(s.processId)===String(context.processId))){ElMessage.warning('下一工序不可用，请重新选择');return}
 processId.value=String(context.processId);processChanged();
}
watch(lineVisible,v=>{if(v){lineQuantityInput.value=undefined;lineForm.value?.clearValidate()}})
watch(visible,v=>{if(v){completedQuantityInput.value=undefined;headerForm.value?.clearValidate()}})
